CREATE TABLE passagem_ficha_anestesica (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, ficha_anestesica_id BIGINT UNSIGNED NOT NULL, sequencia SMALLINT UNSIGNED NOT NULL, momento DATETIME(3) NOT NULL, de_profissional_id BIGINT UNSIGNED NOT NULL, para_profissional_id BIGINT UNSIGNED NOT NULL, resumo VARCHAR(1000) NOT NULL, <auditoria padrão>, CONSTRAINT ck_passagem_ficha_anestesica_pessoas CHECK (de_profissional_id <> para_profissional_id), UNIQUE KEY uq_passagem_ficha_anestesica_sequencia (ficha_anestesica_id, sequencia));
CREATE TABLE lacuna_ficha_anestesica (id ..., ficha_anestesica_id BIGINT UNSIGNED NOT NULL, inicio DATETIME(3) NOT NULL, fim DATETIME(3) NOT NULL, motivo VARCHAR(500) NOT NULL, profissional_id BIGINT UNSIGNED NULL, <auditoria>, CONSTRAINT ck_lacuna_ficha_anestesica_periodo CHECK (fim > inicio));
CREATE TABLE adendo_ficha_anestesica (id ..., ficha_anestesica_id BIGINT UNSIGNED NOT NULL, sequencia SMALLINT UNSIGNED NOT NULL, texto TEXT NOT NULL, profissional_id BIGINT UNSIGNED NOT NULL, <auditoria>, UNIQUE KEY (ficha_anestesica_id, sequencia)); FKs ON DELETE RESTRICT. Também ficha_anestesica.hash_assinatura CHAR(64) NULL e assinada_por_profissional_id.
